CustomField.formula:
IF(ISNULL( Tech_Support_Completed__c ), "",(
LPAD ( TEXT( Day( DateValue(Tech_Support_Completed__c ) ) ) ,2, '0' ) +'/'+ LPAD ( TEXT( MONTH( DateValue(Tech_Support_Completed__c) ) ) ,2, '0' ) +'/'+ TEXT( YEAR( DateValue(Tech_Support_Completed__c ) ) ) + ' - ' + LEFT(TEXT(TIMEVALUE(Tech_Support_Completed__c + (1/24))), 5)
)
)
